<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{ArrowRight,Boxes}from'lucide-vue-next';import{api,session}from'../api';const username=ref('admin'),password=ref(''),error=ref(''),loading=ref(false),router=useRouter();async function submit(){loading.value=true;error.value='';try{const r=await api<{token:string}>('/api/auth/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});session.token=r.token;router.push('/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}</script>
<template><main class="login-page"><section class="login-brand"><div class="login-mark"><Boxes/></div><span>PRODUCT SERVER</span><h1>从产物到部署，<br>保持流程清晰。</h1><p>集中保存 CI 产物，以可视化工作流安全地交付到你的服务器。</p><div class="login-lines"><i></i><i></i><i></i></div></section><section class="card login-card"><div><span class="eyebrow">欢迎回来</span><h2>登录控制台</h2><p>使用管理员账号继续。</p></div><form @submit.prevent="submit"><label>用户名<input v-model="username" required autocomplete="username"></label><label>密码<input v-model="password" type="password" required autofocus autocomplete="current-password"></label><p v-if="error" class="error">{{error}}</p><button class="btn login-submit" :disabled="loading">{{loading?'正在登录…':'登录'}}<ArrowRight/></button></form><small>Product Server · 私有产物交付平台</small></section></main></template>
